WITH unpacked AS (SELECT id, plan, effective_from, tier_limits, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT id, plan, avg_tier_price, DENSE_RANK() OVER (PARTITION BY plan ORDER BY avg_tier_price DESC NULLS LAST) AS avg_tier_price_dense_rank, SUM(avg_tier_price) OVER (PARTITION BY plan ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_tier_price, FIRST_VALUE(avg_tier_price) IGNORE NULLS OVER (PARTITION BY plan ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_avg_tier_price FROM unpacked WHERE plan = 'enterprise';
